def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if h < 2:
        return out

    # The bottom-row 5s mark vertical beams. Extend each beam upward,
    # carrying the colors already present in that column.
    for c in range(w):
        if grid[h - 1][c] != 5:
            continue
        sources = [(r, grid[r][c]) for r in range(h - 1) if grid[r][c] != 0]
        for r in range(h - 1):
            if sources:
                sr, color = min(sources, key=lambda p: abs(p[0] - r))
                out[r][c] = color
        out[h - 1][c] = 5
    return out
